    "ᴍᴛꜱ vᴇᴛɢᴏʟᴅ 100s 體外震波儀": "ᴍᴛꜱ vᴇᴛɢᴏʟᴅ 100s 體外震波儀",
    "#非侵入性 慢性創新治療法\n\n⭓ 震波效應使細胞膜通透性改變，增長性的誘導，對神經影響抗發炎作用，釋放生長因子達到抗菌效果，並使幹細胞遷移及分化，達到修復再生效果。\n\n⭓ 因此在骨科治療領域之臨床證實，獸醫發現在治療馬的骨折、肌腱和韌帶損傷方面的修復情況。迄今為止，震波療法在小動物的臨床治療中也取得良好的修復效果。": "#非侵入性 慢性創新治療法\n\n⭓ 震波效應使細胞膜通透性改變，增長性的誘導，對神經影響抗發炎作用，釋放生長因子達到抗菌效果，並使幹細胞遷移及分化，達到修復再生效果。\n\n⭓ 因此在骨科治療領域之臨床證實，獸醫發現在治療馬的骨折、肌腱和韌帶損傷方面的修復情況。迄今為止，震波療法在小動物的臨床治療中也取得良好的修復效果。",
