    "HY-230 基本款 \n容量：16公升\n操作上簡單，有過熱保護的安全裝置裝置\n\n歡迎動物醫院醫師及美業人員洽詢，謝謝您~~~": "HY-230 基本款 \n容量：16公升\n操作上簡單，有過熱保護的安全裝置裝置\n\n歡迎動物醫院醫師及美業人員洽詢，謝謝您~~~",
    "掌上型血氧濃度儀": "掌上型血氧濃度儀",
    "ACARE AH-MX 掌上型血氧濃度儀\nAcare掌上型血氧濃度儀利用紅外線\n以非侵入式來測動物血液中的含氧量及心跳值,\n其目地在於快速的取得動物之動脈血液含氧值\n進行必要之救護與協助醫護人員進行輔助\n診斷與觀察, ACARE眾里掌上型血氧濃度儀為\n一個方便攜帶,操作簡便, 量測穩定的生理監測設備。": "ACARE AH-MX 掌上型血氧濃度儀\nAcare掌上型血氧濃度儀利用紅外線\n以非侵入式來測動物血液中的含氧量及心跳值,\n其目地在於快速的取得動物之動脈血液含氧值\n進行必要之救護與協助醫護人員進行輔助\n診斷與觀察, ACARE眾里掌上型血氧濃度儀為\n一個方便攜帶,操作簡便, 量測穩定的生理監測設備。",
