    "軟式內視鏡": "軟式內視鏡",
    "當需要檢查彎曲的管道舉例:消化道、支氣管道時..\n軟式內視鏡可以達成某種程度彎折來配合管道彎曲\n更方便更加深入管道內了解其內部狀況。\n主要適用於消化道、咽喉氣管的檢查、採樣、異物取出等..\n\n歡迎醫師洽詢": "當需要檢查彎曲的管道舉例:消化道、支氣管道時..\n軟式內視鏡可以達成某種程度彎折來配合管道彎曲\n更方便更加深入管道內了解其內部狀況。\n主要適用於消化道、咽喉氣管的檢查、採樣、異物取出等..\n\n歡迎醫師洽詢",
