    "✱ 主要用於預防動物在手術中失溫，或術後體溫保暖等作用。\n\n✱ 溫風毯機通過一根軟管連接到升溫氣墊，\n暖氣在主機中產生，通過該軟管吹入氣墊中。\n\n✱ 「升溫氣墊被」放置在手術病患寵物周圍上身或下身。\n升溫氣墊被上的小孔，能使暖氣平均分散到患寵身上。\n\n✱ 此外，環境條件可能導致病患寵物體溫下降，\n使用溫風毯機則可做為提供舒適恆溫保暖的最佳效果。\n\n✱ 溫風毯機對成年寵物或幼寵均適用。": "✱ 主要用於預防動物在手術中失溫，或術後體溫保暖等作用。\n\n✱ 溫風毯機通過一根軟管連接到升溫氣墊，\n暖氣在主機中產生，通過該軟管吹入氣墊中。\n\n✱ 「升溫氣墊被」放置在手術病患寵物周圍上身或下身。\n升溫氣墊被上的小孔，能使暖氣平均分散到患寵身上。\n\n✱ 此外，環境條件可能導致病患寵物體溫下降，\n使用溫風毯機則可做為提供舒適恆溫保暖的最佳效果。\n\n✱ 溫風毯機對成年寵物或幼寵均適用。",
