    "祐強醫療儀器有限公司擁有超過 20 年的專業經驗，我們致力於提供醫療機構優質的設備與服務。": "祐强医疗仪器有限公司拥有超过 20 年的专业经验，我们致力于为医疗机构提供优质设备与服务。",
    "聯絡專員": "联系专员",
    "正在載入產品分類...": "正在载入产品分类...",
    "目前無法載入產品分類，請稍後再試。": "目前无法载入产品分类，请稍后再试。",
    "祐強醫療儀器有限公司致力於寵物醫院、醫療設備推廣應用，寵物傷口照護及寵物天然保健食品": "祐强医疗仪器有限公司致力于宠物医院、医疗设备推广应用，宠物伤口照护及宠物天然保健食品",
    "平台上已經累積與獸醫師在臨床使用上有非常顯著的效果與經驗。": "平台上已经累积与兽医师在临床使用上有非常显著的效果与经验。",
    "祐強醫療儀器有限公司致力於寵物醫院、醫療設備推廣應用，並提供寵物傷口照護及寵物天然保健食品等專業產品與服務。": "祐强医疗仪器有限公司致力于宠物医院、医疗设备推广应用，并提供宠物伤口照护及宠物天然保健食品等专业产品与服务。",
    "我們長期累積與獸醫師臨床合作的實際經驗，重視產品品質、專業應用與完善服務，協助醫療單位找到合適的解決方案。": "我们长期累积与兽医师临床合作的实际经验，重视产品品质、专业应用与完善服务，协助医疗单位找到合适的解决方案。",
    "秉持「竭盡所能、盡心服務」的理念，祐強持續以專業、可靠的服務，與醫師及醫療機構共同提升照護品質。": "秉持「竭尽所能、尽心服务」的理念，祐强持续以专业、可靠的服务，与医师及医疗机构共同提升照护品质。",
    "我們隨時準備為您提供專業協助": "我们随时准备为您提供专业协助",
    "無論是產品諮詢、設備應用或售後服務歡迎透過以下方式與我們聯繫，我們將盡快為您提供協助。": "无论是产品咨询、设备应用或售后服务欢迎通过以下方式与我们联系，我们将尽快为您提供协助。",
    "透過實際產品影片快速了解設備功能、影像表現與臨床應用， 提供更直覺的產品資訊與操作參考。": "通过实际产品影片快速了解设备功能、影像表现与临床应用，提供更直观的产品信息与操作参考。",
