    "目前使用中": "Current Session",
    "目前沒有符合條件的登入記錄": "No login records match the current filters",
    "祐強醫療儀器有限公司擁有超過 20 年的專業經驗，我們致力於提供醫療機構優質的設備與服務。": "With more than 20 years of professional experience, YoChung Medical is committed to providing healthcare institutions with quality equipment and service.",
    "聯絡專員": "Contact Specialist",
    "正在載入產品分類...": "Loading product categories...",
    "目前無法載入產品分類，請稍後再試。": "Unable to load product categories. Please try again later.",
    "祐強醫療儀器有限公司致力於寵物醫院、醫療設備推廣應用，寵物傷口照護及寵物天然保健食品": "YoChung Medical focuses on veterinary hospitals, medical equipment applications, pet wound care, and natural pet health products.",
    "平台上已經累積與獸醫師在臨床使用上有非常顯著的效果與經驗。": "We have accumulated extensive clinical experience with veterinarians and achieved notable results in real-world use.",
    "祐強醫療儀器有限公司致力於寵物醫院、醫療設備推廣應用，並提供寵物傷口照護及寵物天然保健食品等專業產品與服務。": "YoChung Medical serves veterinary hospitals and promotes medical equipment applications while providing professional pet wound-care products and natural health products.",
    "我們長期累積與獸醫師臨床合作的實際經驗，重視產品品質、專業應用與完善服務，協助醫療單位找到合適的解決方案。": "Through long-term clinical collaboration with veterinarians, we focus on product quality, professional application, and comprehensive service to help medical institutions find the right solutions.",
    "秉持「竭盡所能、盡心服務」的理念，祐強持續以專業、可靠的服務，與醫師及醫療機構共同提升照護品質。": "Guided by our commitment to doing our utmost and serving wholeheartedly, YoChung delivers professional, reliable service and works with clinicians and institutions to improve quality of care.",
    "我們隨時準備為您提供專業協助": "We are ready to provide professional assistance",
    "無論是產品諮詢、設備應用或售後服務歡迎透過以下方式與我們聯繫，我們將盡快為您提供協助。": "For product inquiries, equipment applications, or after-sales service, contact us through any of the methods below. We will assist you as soon as possible.",
    "透過實際產品影片快速了解設備功能、影像表現與臨床應用， 提供更直覺的產品資訊與操作參考。": "Learn about equipment functions, image performance, and clinical applications through real product videos, with intuitive product information and operating references.",
