    "目前使用中": "現在使用中",
    "目前沒有符合條件的登入記錄": "条件に一致するログイン履歴はありません",
    "祐強醫療儀器有限公司擁有超過 20 年的專業經驗，我們致力於提供醫療機構優質的設備與服務。": "祐強医療機器は20年以上の専門経験を持ち、医療機関に高品質な設備とサービスを提供しています。",
    "聯絡專員": "担当者に連絡",
    "正在載入產品分類...": "製品カテゴリを読み込み中...",
    "目前無法載入產品分類，請稍後再試。": "製品カテゴリを読み込めません。しばらくしてから再度お試しください。",
    "祐強醫療儀器有限公司致力於寵物醫院、醫療設備推廣應用，寵物傷口照護及寵物天然保健食品": "祐強医療は、動物病院向け医療機器の活用、ペットの創傷ケア、天然健康食品に取り組んでいます。",
    "平台上已經累積與獸醫師在臨床使用上有非常顯著的效果與經驗。": "獣医師との臨床使用を通じて豊富な経験を蓄積し、高い効果を確認しています。",
    "祐強醫療儀器有限公司致力於寵物醫院、醫療設備推廣應用，並提供寵物傷口照護及寵物天然保健食品等專業產品與服務。": "祐強医療は動物病院向け医療機器の活用を支援し、ペットの創傷ケア製品や天然健康食品などの専門製品・サービスを提供しています。",
    "我們長期累積與獸醫師臨床合作的實際經驗，重視產品品質、專業應用與完善服務，協助醫療單位找到合適的解決方案。": "獣医師との長年の臨床協力で得た経験を活かし、製品品質、専門的な活用、充実したサービスを重視し、医療機関に最適な解決策を提供します。",
    "秉持「竭盡所能、盡心服務」的理念，祐強持續以專業、可靠的服務，與醫師及醫療機構共同提升照護品質。": "「最善を尽くし、心を込めてサービスする」という理念のもと、祐強は専門的で信頼できるサービスを提供し、医師・医療機関と共にケアの質向上に取り組みます。",
    "我們隨時準備為您提供專業協助": "専門的なサポートをご提供します",
    "無論是產品諮詢、設備應用或售後服務歡迎透過以下方式與我們聯繫，我們將盡快為您提供協助。": "製品相談、機器の活用、アフターサービスなど、以下の方法でお気軽にお問い合わせください。できるだけ早く対応いたします。",
    "透過實際產品影片快速了解設備功能、影像表現與臨床應用， 提供更直覺的產品資訊與操作參考。": "実際の製品動画を通して、機器の機能、画像性能、臨床活用をわかりやすくご紹介します。",
