    "百威特-DRF 40": "バイウェイト-DRF 40",
    "👉 百威特 DRF40 幫你大幅縮短檢查時間、提升診療效率！💪💪💪\n💥 一鍵啟動｜即時數位X光高畫質成像\n💥 數位攝影＋透視功能｜動態影像即時掌握\n💥 縮短診療時間｜提升臨床效率與精準度": "👉 Baiweite DRF40 は、検査時間を大幅に短縮し、診断と治療の効率を向上させるのに役立ちます。 💪💪💪\n💥 ワンクリックスタート｜リアルタイムデジタルX線高精細画像撮影\n💥 デジタル写真 + 遠近法機能 |動的な画像のリアルタイム制御\n💥 診断と治療時間の短縮 |臨床の効率と精度を向上させる",
