    "祐強醫療儀器有限公司致力於寵物醫院、醫療設備推廣應用，並提供寵物傷口照護及寵物天然保健食品等專業產品與服務。": "요청 메디컬은 동물병원과 의료 장비 활용을 지원하며 반려동물 상처 관리 제품과 천연 건강제품 등 전문 제품과 서비스를 제공합니다.",
    "我們長期累積與獸醫師臨床合作的實際經驗，重視產品品質、專業應用與完善服務，協助醫療單位找到合適的解決方案。": "수의사와의 장기적인 임상 협력을 통해 쌓은 경험을 바탕으로 제품 품질, 전문적 활용, 완벽한 서비스를 중시하며 의료기관에 적합한 솔루션을 제공합니다.",
    "秉持「竭盡所能、盡心服務」的理念，祐強持續以專業、可靠的服務，與醫師及醫療機構共同提升照護品質。": "최선을 다하고 정성을 다해 서비스한다는 철학 아래 요청은 전문적이고 신뢰할 수 있는 서비스를 제공하며 의료진 및 의료기관과 함께 돌봄의 질을 높입니다.",
    "我們隨時準備為您提供專業協助": "전문적인 도움을 드릴 준비가 되어 있습니다",
    "無論是產品諮詢、設備應用或售後服務歡迎透過以下方式與我們聯繫，我們將盡快為您提供協助。": "제품 문의, 장비 활용, 애프터서비스가 필요하시면 아래 방법으로 연락해 주세요. 최대한 빠르게 도와드리겠습니다.",
    "透過實際產品影片快速了解設備功能、影像表現與臨床應用， 提供更直覺的產品資訊與操作參考。": "실제 제품 영상을 통해 장비 기능, 영상 성능, 임상 활용을 빠르게 이해하고 직관적인 제품 정보와 사용 참고를 확인할 수 있습니다.",
