    "祐強醫療儀器有限公司擁有超過 20 年的專業經驗，我們致力於提供醫療機構優質的設備與服務。": "Với hơn 20 năm kinh nghiệm chuyên môn, YoChung Medical cam kết cung cấp thiết bị và dịch vụ chất lượng cho các cơ sở y tế.",
    "聯絡專員": "Liên hệ chuyên viên",
    "正在載入產品分類...": "Đang tải danh mục sản phẩm...",
    "目前無法載入產品分類，請稍後再試。": "Không thể tải danh mục sản phẩm. Vui lòng thử lại sau.",
    "祐強醫療儀器有限公司致力於寵物醫院、醫療設備推廣應用，寵物傷口照護及寵物天然保健食品": "YoChung Medical tập trung vào bệnh viện thú y, ứng dụng thiết bị y tế, chăm sóc vết thương và sản phẩm sức khỏe tự nhiên cho thú cưng.",
    "平台上已經累積與獸醫師在臨床使用上有非常顯著的效果與經驗。": "Chúng tôi đã tích lũy nhiều kinh nghiệm lâm sàng cùng bác sĩ thú y và đạt hiệu quả rõ rệt trong thực tế sử dụng.",
    "祐強醫療儀器有限公司致力於寵物醫院、醫療設備推廣應用，並提供寵物傷口照護及寵物天然保健食品等專業產品與服務。": "YoChung Medical phục vụ bệnh viện thú y, thúc đẩy ứng dụng thiết bị y tế và cung cấp sản phẩm chăm sóc vết thương cùng sản phẩm sức khỏe tự nhiên cho thú cưng.",
    "我們長期累積與獸醫師臨床合作的實際經驗，重視產品品質、專業應用與完善服務，協助醫療單位找到合適的解決方案。": "Từ kinh nghiệm hợp tác lâm sàng lâu dài với bác sĩ thú y, chúng tôi chú trọng chất lượng sản phẩm, ứng dụng chuyên môn và dịch vụ toàn diện để giúp các đơn vị y tế tìm giải pháp phù hợp.",
    "秉持「竭盡所能、盡心服務」的理念，祐強持續以專業、可靠的服務，與醫師及醫療機構共同提升照護品質。": "Với triết lý tận tâm phục vụ và nỗ lực hết mình, YoChung cung cấp dịch vụ chuyên nghiệp, đáng tin cậy và đồng hành cùng đội ngũ y tế để nâng cao chất lượng chăm sóc.",
    "我們隨時準備為您提供專業協助": "Chúng tôi luôn sẵn sàng hỗ trợ chuyên nghiệp",
    "無論是產品諮詢、設備應用或售後服務歡迎透過以下方式與我們聯繫，我們將盡快為您提供協助。": "Dù là tư vấn sản phẩm, ứng dụng thiết bị hay hậu mãi, hãy liên hệ với chúng tôi qua các kênh bên dưới. Chúng tôi sẽ hỗ trợ sớm nhất có thể.",
    "透過實際產品影片快速了解設備功能、影像表現與臨床應用， 提供更直覺的產品資訊與操作參考。": "Tìm hiểu nhanh chức năng thiết bị, chất lượng hình ảnh và ứng dụng lâm sàng qua video sản phẩm thực tế, với thông tin và hướng dẫn trực quan.",
