    "YoChung Medical, 祐強, 醫療器材, 醫療設備, 醫療供應商, 醫療維修, 醫療租賃, 醫療技術, 醫療物流, 醫療服務, 醫療解決方案": "YoChung Medical, YoChung, thiết bị y tế, thiết bị y tế, nhà cung cấp y tế, bảo trì y tế, cho thuê y tế, công nghệ y tế, hậu cần y tế, dịch vụ y tế, giải pháp y tế",
    "專業醫療設備供應與技術支援，打造高品質、高效率的醫療環境。": "Cung cấp trang thiết bị y tế chuyên nghiệp và hỗ trợ kỹ thuật tạo nên môi trường y tế chất lượng cao và hiệu quả.",
