    "關於祐強｜祐強醫療儀器有限公司": "Giới thiệu về Youqiang｜Công ty TNHH dụng cụ y tế Youqiang",
    "了解祐強醫療儀器有限公司的公司理念、寵物醫療設備、傷口照護與專業服務方向。": "Hiểu triết lý công ty, thiết bị y tế thú cưng, chăm sóc vết thương và định hướng dịch vụ chuyên nghiệp của Công ty TNHH Dụng cụ Y tế Youqiang.",
    "專業與實證導向": "Chuyên nghiệp và dựa trên bằng chứng",
    "致力於與獸醫臨床合作，累積使用經驗與療效，提供實證基礎的醫療產品與設備。": "Cam kết hợp tác lâm sàng với bác sĩ thú y, tích lũy kinh nghiệm và hiệu quả, đồng thời cung cấp các sản phẩm và thiết bị y tế dựa trên bằng chứng.",
    "秉持「竭盡所能、盡心服務」的理念，為專業醫師與臨床需求提供對應服務。": "Tuân thủ quan niệm \"làm hết sức mình và phục vụ bằng sự cống hiến\", chúng tôi cung cấp các dịch vụ tương ứng với các bác sĩ chuyên nghiệp và nhu cầu lâm sàng.",
    "提供高品質的醫療器材，推動醫療技術與設備應用的創新與整合。": "Cung cấp thiết bị y tế chất lượng cao và thúc đẩy đổi mới, tích hợp các ứng dụng công nghệ và thiết bị y tế.",
    "共同創造照與善的目標": "Cùng nhau hợp tác để tạo ra mục tiêu soi sáng và lòng nhân ái",
    "與醫師、醫療機構共創「照護」與「完善」的醫療服務願景。": "Làm việc với các bác sĩ và cơ sở y tế để tạo ra tầm nhìn về dịch vụ y tế là “chăm sóc” và “hoàn hảo”.",
    "舒派特系列": "Dòng Shupait",
    "專業傷口護理系列產品，適用於各種動物傷口處理。": "Dòng sản phẩm chăm sóc vết thương chuyên nghiệp, phù hợp với nhiều phương pháp điều trị vết thương cho động vật.",
