    "結合「數位X光攝影（DR）」與「即時透視影像（Fluoroscopy）」功能於一機的高階影像系統。其設計著重於臨床多功能應用、空間利用效率與操作便利性。": "Một hệ thống hình ảnh cao cấp kết hợp các chức năng của \"Chụp ảnh X-quang kỹ thuật số (DR)\" và \"Nội soi huỳnh quang thời gian thực\" trong một máy. Thiết kế của nó tập trung vào các ứng dụng đa chức năng lâm sàng, hiệu quả sử dụng không gian và sự thuận tiện trong vận hành.",
