    "歡迎洽詢": "Chào mừng bạn đến hỏi thăm",
    "鋇劑": "Bari",
    "Optiray 350 造影劑": "Chất tương phản Optiray 350",
    "直葉喉頭鏡": "Ống soi thanh quản lưỡi thẳng",
    "動物溫風毯機": "Máy làm chăn hơi ấm cho động vật",
    "✱ 主要用於預防動物在手術中失溫，或術後體溫保暖等作用。\n\n✱ 溫風毯機通過一根軟管連接到升溫氣墊，\n暖氣在主機中產生，通過該軟管吹入氣墊中。\n\n✱ 「升溫氣墊被」放置在手術病患寵物周圍上身或下身。\n升溫氣墊被上的小孔，能使暖氣平均分散到患寵身上。\n\n✱ 此外，環境條件可能導致病患寵物體溫下降，\n使用溫風毯機則可做為提供舒適恆溫保暖的最佳效果。\n\n✱ 溫風毯機對成年寵物或幼寵均適用。": "✱ Chủ yếu dùng để phòng ngừa động vật bị hạ thân nhiệt trong quá trình phẫu thuật hoặc giữ ấm cơ thể sau phẫu thuật.\n\n✱ Máy chăn hơi ấm được nối với nệm hơi sưởi thông qua một ống mềm.\nKhông khí ấm được tạo ra trong bộ phận chính và thổi vào đệm hơi qua ống này.\n\n✱ \"Đệm hơi sưởi\" được đặt xung quanh phần trên hoặc phần dưới cơ thể của thú cưng của bệnh nhân phẫu thuật.\nCác lỗ nhỏ trên đệm hơi được sưởi ấm có thể phân phối nhiệt đều đến cơ thể bệnh nhân.\n\n✱ Ngoài ra, điều kiện môi trường có thể khiến nhiệt độ cơ thể của vật nuôi bị bệnh giảm xuống,\nSử dụng máy làm chăn hơi ấm có thể mang lại hiệu quả tốt nhất là mang lại nhiệt độ ấm áp thoải mái và ổn định.\n\n✱ Máy chăn hơi ấm phù hợp cho cả thú cưng trưởng thành và thú cưng còn nhỏ.",
