    "祐強醫療儀器有限公司擁有超過 20 年的專業經驗，我們致力於提供醫療機構優質的設備與服務。": "ด้วยประสบการณ์มากกว่า 20 ปี YoChung Medical มุ่งมั่นให้บริการอุปกรณ์และบริการคุณภาพแก่สถานพยาบาล",
    "聯絡專員": "ติดต่อผู้เชี่ยวชาญ",
    "正在載入產品分類...": "กำลังโหลดหมวดหมู่สินค้า...",
    "目前無法載入產品分類，請稍後再試。": "ไม่สามารถโหลดหมวดหมู่สินค้าได้ โปรดลองอีกครั้งภายหลัง",
    "祐強醫療儀器有限公司致力於寵物醫院、醫療設備推廣應用，寵物傷口照護及寵物天然保健食品": "YoChung Medical มุ่งเน้นโรงพยาบาลสัตว์ การใช้อุปกรณ์ทางการแพทย์ การดูแลบาดแผล และผลิตภัณฑ์สุขภาพธรรมชาติสำหรับสัตว์เลี้ยง",
    "平台上已經累積與獸醫師在臨床使用上有非常顯著的效果與經驗。": "เราได้สั่งสมประสบการณ์ทางคลินิกร่วมกับสัตวแพทย์และเห็นผลลัพธ์ที่ชัดเจนในการใช้งานจริง",
    "祐強醫療儀器有限公司致力於寵物醫院、醫療設備推廣應用，並提供寵物傷口照護及寵物天然保健食品等專業產品與服務。": "YoChung Medical ให้บริการโรงพยาบาลสัตว์ ส่งเสริมการใช้อุปกรณ์ทางการแพทย์ และนำเสนอผลิตภัณฑ์ดูแลบาดแผลกับผลิตภัณฑ์สุขภาพธรรมชาติสำหรับสัตว์เลี้ยง",
    "我們長期累積與獸醫師臨床合作的實際經驗，重視產品品質、專業應用與完善服務，協助醫療單位找到合適的解決方案。": "จากประสบการณ์ความร่วมมือทางคลินิกกับสัตวแพทย์มาอย่างยาวนาน เราให้ความสำคัญกับคุณภาพสินค้า การใช้งานอย่างมืออาชีพ และบริการครบวงจร เพื่อช่วยหน่วยงานการแพทย์เลือกโซลูชันที่เหมาะสม",
    "秉持「竭盡所能、盡心服務」的理念，祐強持續以專業、可靠的服務，與醫師及醫療機構共同提升照護品質。": "ด้วยแนวคิดทุ่มเทอย่างเต็มที่และบริการด้วยใจ YoChung มอบบริการที่เป็นมืออาชีพและเชื่อถือได้ พร้อมร่วมมือกับบุคลากรและสถานพยาบาลเพื่อยกระดับคุณภาพการดูแล",
    "我們隨時準備為您提供專業協助": "เราพร้อมให้ความช่วยเหลืออย่างมืออาชีพ",
    "無論是產品諮詢、設備應用或售後服務歡迎透過以下方式與我們聯繫，我們將盡快為您提供協助。": "ไม่ว่าจะเป็นการสอบถามสินค้า การใช้งานอุปกรณ์ หรือบริการหลังการขาย สามารถติดต่อเราได้ตามช่องทางด้านล่าง เราจะช่วยเหลือโดยเร็วที่สุด",
    "透過實際產品影片快速了解設備功能、影像表現與臨床應用， 提供更直覺的產品資訊與操作參考。": "เรียนรู้ฟังก์ชันอุปกรณ์ คุณภาพภาพ และการใช้งานทางคลินิกผ่านวิดีโอสินค้าจริง พร้อมข้อมูลและแนวทางใช้งานที่เข้าใจง่าย",
